INSERT INTO DISCHARGE_NOTES VALUES
  (1, 'SIM1001', '2026-10-30', 77, 'COPD exacerbation', 6, '77-year-old female admitted for COPD exacerbation, length of stay 6 days. One prior admission in the last 12 months. Lives alone. Discharged home on an albuterol inhaler and a prednisone taper; 8 active medications at discharge. Denies shortness of breath at rest. Follow up with pulmonology in 7 days. Call the clinic with any new symptoms.', 'I felt ignored and I still do not know who to call if I get worse.'),
  (2, 'SIM1002', '2026-10-03', 47, 'Cellulitis', 1, '47-year-old female admitted for cellulitis, length of stay 1 day. No prior admissions in the last 12 months. Lives with family. Discharged home on cephalexin; 12 active medications at discharge. Follow up with primary care in 2 weeks. Call the clinic with any new symptoms.', 'The nurses were kind and explained every medication clearly.'),
  (3, 'SIM1003', '2026-10-14', 42, 'Sepsis, urinary source', 7, '42-year-old male admitted for sepsis, urinary source, length of stay 7 days. No prior admissions in the last 12 months. Lives with family. Discharged home on cephalexin; 3 active medications at discharge. Afebrile for 48 hours before discharge. No follow-up appointment was scheduled before discharge. Call the clinic with any new symptoms.', 'Nothing special to report. Parking was hard to find.'),
  (4, 'SIM1004', '2026-11-05', 56, 'Heart failure', 2, '56-year-old male admitted for heart failure, length of stay 2 days. No prior admissions in the last 12 months. Lives alone. Discharged home on furosemide and metoprolol; 13 active medications at discharge. Weight down 3 kg after diuresis. Follow up with cardiology in 3 days. Call the clinic with any new symptoms.', 'The stay was okay. Food was average.'),
  (5, 'SIM1005', '2026-10-16', 79, 'Cellulitis', 1, '79-year-old male admitted for cellulitis, length of stay 1 day. No prior admissions in the last 12 months. Lives alone. Discharged home on cephalexin; 12 active medications at discharge. Follow up with primary care in 1 month. Call the clinic with any new symptoms.', 'Discharge took a few hours but the paperwork was fine.'),
  (6, 'SIM1006', '2026-11-06', 46, 'Hip replacement', 2, '46-year-old male admitted for hip replacement, length of stay 2 days. No prior admissions in the last 12 months. Lives with spouse. Discharged home on apixaban and acetaminophen; 13 active medications at discharge. No history of falls. Denies shortness of breath. Follow up with orthopedics in 3 days. Return to the ED for fever, chest pain, or trouble breathing.', 'Dr. Lee listened to us and the team made me feel safe.'),
  (7, 'SIM1007', '2026-10-18', 50, 'COPD exacerbation', 1, '50-year-old female admitted for COPD exacerbation, length of stay 1 day. No prior admissions in the last 12 months. Lives alone. Discharged home on an albuterol inhaler and a prednisone taper; 10 active medications at discharge. Still short of breath on stairs. Follow up with pulmonology in 2 weeks. Return to the ED for fever, chest pain, or trouble breathing.', 'Terrible night, the call light went unanswered for an hour.'),
  (8, 'SIM1008', '2026-11-09', 55, 'Heart failure', 5, '55-year-old female admitted for heart failure, length of stay 5 days. No prior admissions in the last 12 months. Lives with daughter. Discharged home on furosemide and metoprolol; 6 active medications at discharge. Weight down 3 kg after diuresis. No follow-up appointment was scheduled before discharge. Call the clinic with any new symptoms.', 'Terrible night, the call light went unanswered for an hour.'),
  (9, 'SIM1009', '2026-10-03', 42, 'Cellulitis', 5, '42-year-old female admitted for cellulitis, length of stay 5 days. 2 prior admissions in the last 12 months. Lives with family. Discharged home on cephalexin; 7 active medications at discharge. Follow up with primary care in 5 days. Call the clinic with any new symptoms.', 'Nobody explained my new medicines and I am confused and worried.'),
