-- Day 37: load 40 SIMULATED discharge notes and the answer key (generated by gen_notes.py, seed 37).
-- Not real patient data. Run after 01_setup.sql.
USE WAREHOUSE DS90_XS;
USE SCHEMA DS90.DAY37;

CREATE OR REPLACE TABLE DISCHARGE_NOTES (
  NOTE_ID INT, PATIENT_ID STRING, DISCHARGE_DATE DATE, AGE INT,
  DIAGNOSIS STRING, LOS_DAYS INT, NOTE_TEXT STRING, PATIENT_FEEDBACK STRING);


CREATE OR REPLACE TABLE NOTE_LABELS (
  NOTE_ID INT, TRUE_RISK_BAND STRING, RISK_POINTS INT,
  TRUE_FOLLOWUP_DAYS INT, TRUE_FOLLOWUP_WITH STRING, TRUE_FEEDBACK_TONE STRING);


SELECT COUNT(*) AS N_NOTES, AVG(LENGTH(NOTE_TEXT)) AS AVG_CHARS FROM DISCHARGE_NOTES;
SELECT TRUE_RISK_BAND, COUNT(*) FROM NOTE_LABELS GROUP BY 1 ORDER BY 1;
